const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // A transect line across the Mississippi River near Memphis, TN.
    const transect = ee.Geometry.LineString([
        [-90.10, 35.15],
        [-90.02, 35.15]
    ]);

    const startDate2021 = '2021-09-01';
    const endDate2021 = '2021-09-30';
    const startDate2023 = '2023-09-01';
    const endDate2023 = '2023-09-30';

    // 2. Data Acquisition & Check
    const gsw = ee.ImageCollection('JRC/GSW1_4/MonthlyHistory');

    const image2021 = gsw.filterDate(startDate2021, endDate2021).first();
    const image2023 = gsw.filterDate(startDate2023, endDate2023).first();

    // The JRC dataset is a complete global product, but we check for existence anyway.
    const image2021Exists = ee.Number(ee.List([image2021]).flatten().size());
    const image2023Exists = ee.Number(ee.List([image2023]).flatten().size());

    if (image2021Exists.getInfo() === 0 || image2023Exists.getInfo() === 0) {
        console.log(`Data availability: 2021=${image2021Exists.getInfo()}, 2023=${image2023Exists.getInfo()}`);
        console.log("C1: Empty Collection");
        return;
    }

    // 3. Processing
    // Create a binary water mask. Water is class 1 (seasonal) or 2 (permanent).
    const waterMask2021 = image2021.select('water').gte(1);
    const waterMask2023 = image2023.select('water').gte(1);

    const scale = 30; // Native resolution of JRC GSW dataset

    // 4. Calculation
    // We count the number of water pixels along the transect line.
    // The sum of a binary mask gives the count of pixels with value 1.
    const stats2021 = waterMask2021.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: transect,
        scale: scale,
        maxPixels: 1e9
    });

    const stats2023 = waterMask2023.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: transect,
        scale: scale,
        maxPixels: 1e9
    });

    const width2021 = ee.Number(stats2021.get('water'));
    const width2023 = ee.Number(stats2023.get('water'));

    const width2021Val = width2021.getInfo();
    const width2023Val = width2023.getInfo();

    // 5. Validation & Final Answer
    if (width2021Val === null || width2023Val === null) {
        console.log("Calculation resulted in null.");
        console.log("C3");
        return;
    }

    if (width2021Val === 0 && width2023Val === 0) {
        console.log("No water pixels found along the transect for both periods.");
        console.log("C2");
        return;
    }

    const widthMeters2021 = width2021Val * scale;
    const widthMeters2023 = width2023Val * scale;

    console.log(`September 2021 Water Pixel Count: ${width2021Val} (~${widthMeters2021.toFixed(0)} m width)`);
    console.log(`September 2023 Water Pixel Count: ${width2023Val} (~${widthMeters2023.toFixed(0)} m width)`);

    if (width2023Val < width2021Val) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e.toString()}`);
    if (e.message.includes('computation timed out') || e.message.includes('memory')) {
        console.log("D");
    } else if (e.name === 'EEException') {
        console.log("D");
    } else {
        console.log("D");
    }
});
